import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.Dg5fKO7V.js";const k=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"Testing.md","filePath":"Testing.md","lastUpdated":1788563284000}'),n={name:"Testing.md"};function o(r,e,d,h,l,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>Different kinds of failure are kept apart, so a red suite tells you where to look before you read a single line of output.</p><h2 id="pick-a-suite" tabindex="-1">Pick a suite <a class="header-anchor" href="#pick-a-suite" aria-label="Permalink to &quot;Pick a suite&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>On its own that prints a menu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which tests should run?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  1  frontend   Frontend only, Vitest</span></span>
<span class="line"><span>  2  rust       Rust only, cargo test</span></span>
<span class="line"><span>  3  system     System workflows, real temporary SQLite</span></span>
<span class="line"><span>  4  network    Network only, the smoke suite plus every provider probe</span></span>
<span class="line"><span>  5  all        All tests, including UI, system, network and coverage</span></span></code></pre></div><p>Every entry answers to its name or its number, so <code>npm test rust</code> and <code>npm test 2</code> do the same thing. Four more suites sit off the menu and are reachable by name only, because each is a slice of one that is on it: <code>ui</code>, <code>coverage</code>, <code>smoke</code> and <code>live</code>.</p><p>Piped or in CI, where there is no terminal to prompt, a bare <code>npm test</code> runs the frontend suite.</p><h2 id="the-suites" tabindex="-1">The suites <a class="header-anchor" href="#the-suites" aria-label="Permalink to &quot;The suites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Command</th><th>Engine</th><th>Leaves the machine</th><th>Proves</th></tr></thead><tbody><tr><td>Frontend</td><td><code>npm run test:frontend</code></td><td>Vitest</td><td>no</td><td>Pure rules, component contracts, and real click, input, focus and keyboard handling in jsdom</td></tr><tr><td>UI</td><td><code>npm run test:ui</code></td><td>Vitest</td><td>no</td><td>The interaction subset of the above, nothing else</td></tr><tr><td>Coverage</td><td><code>npm run test:coverage</code></td><td>Vitest</td><td>no</td><td>The frontend suite with an instrumented run and a report</td></tr><tr><td>Rust</td><td><code>npm run test:rust</code></td><td>cargo</td><td>no</td><td>Parsing, matching, shaping and service logic</td></tr><tr><td>System</td><td><code>npm run test:system</code></td><td>cargo</td><td>no</td><td>Several backend services together against a real temporary SQLite file, including a close and reopen cycle</td></tr><tr><td>Smoke</td><td><code>npm test smoke</code></td><td>cargo</td><td>yes</td><td>The catalogue, metadata and provider pipelines end to end</td></tr><tr><td>Live</td><td><code>npm test live</code></td><td>cargo</td><td>yes</td><td>One probe per provider against the real site</td></tr><tr><td>Network</td><td><code>npm run test:network</code></td><td>cargo</td><td>yes</td><td>Smoke and live together</td></tr><tr><td>Tooling</td><td><code>npm run test:tooling</code></td><td>node:test</td><td>no</td><td>That these scripts keep the contracts the other suites rely on</td></tr><tr><td>Everything</td><td><code>npm test all</code></td><td>all three</td><td>yes</td><td>Every layer, one pass per engine</td></tr></tbody></table><p><code>npm test all</code> is deliberately three passes and not ten. Vitest runs once with coverage on, cargo runs once with <code>--include-ignored</code> and <code>ANISPHERE_SMOKE=1</code> so the offline, system, smoke and live layers all come out of the same compilation, and node:test runs the tooling contracts. Running the suites separately would compile the same code four times.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Both engines take a name filter, and both understand a substring.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nearestTrack</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # one frontend file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;falls through&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # one test, by name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src-tauri/Cargo.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> title_matching</span></span></code></pre></div><p><code>npm run test:ui</code> is a filter and nothing more. Interaction tests name their <code>describe</code> block <code>Interactions</code>, and that word is the whole selector.</p><p>Anything after a bare <code>--</code> reaches the test binary rather than cargo, which is where the harness flags live:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># show output from passing tests too, instead of only failing ones</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src-tauri/Cargo.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nocapture</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># one thread, so interleaved output stays readable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src-tauri/Cargo.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-threads=1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the ignored tests, and only those</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src-tauri/Cargo.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignored</span></span></code></pre></div><h2 id="what-the-network-suite-is" tabindex="-1">What the network suite is <a class="header-anchor" href="#what-the-network-suite-is" aria-label="Permalink to &quot;What the network suite is&quot;">​</a></h2><p>Two groups, gated differently because they fail differently.</p><p><strong>The smoke suite</strong> is gated behind the <code>ANISPHERE_SMOKE</code> environment variable rather than <code>#[ignore]</code>, so it needs a name filter to select. It walks the catalogue, metadata and provider pipelines end to end.</p><p><strong>The provider probes</strong> are marked <code>#[ignore]</code> and sit beside the tests for the module each one exercises. A probe for AniDB parsing belongs next to the AniDB parsing tests rather than in a distant file of its own.</p><p>A failure in either group means an upstream service changed or went down. That is a signal to go look, not a broken build, which is why CI runs them with <code>continue-on-error</code>.</p><p>Some probes skip themselves rather than fail. A site that answers <code>429 Too Many Requests</code> is throttling everyone pointed at it, and its answer says nothing about this code, so the probe prints a <code>[live] skipped</code> line and returns. The runner counts those separately and lists them under the results.</p><p>A few probes read their target from the environment, so you can point one at whatever you are actually debugging:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ANISPHERE_ANINEKO_HANDLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">naruto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANISPHERE_ANINEKO_EP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live</span></span></code></pre></div><h2 id="where-tests-live" tabindex="-1">Where tests live <a class="header-anchor" href="#where-tests-live" aria-label="Permalink to &quot;Where tests live&quot;">​</a></h2><p><strong>Rust tests live in <code>src-tauri/src/tests/</code></strong>, mirroring the module tree, attached to their module with <code>#[cfg(test)] #[path = &quot;...&quot;] mod tests;</code>. Keeping them out of the production file keeps that file about the thing it does.</p><p><strong>Frontend tests live in a <code>tests/</code> folder inside the feature they cover</strong>, so <code>src/features/watch/tests/trackFallback.test.tsx</code> sits with the code it is about. Vitest is for executable product behaviour. Repository-wide architecture, locale, documentation and asset contracts are <a href="#sonar-project-checks">Sonar project checks</a>, not test files.</p><h2 id="writing-tests" tabindex="-1">Writing tests <a class="header-anchor" href="#writing-tests" aria-label="Permalink to &quot;Writing tests&quot;">​</a></h2><p><strong>Name the behaviour, not the function.</strong> <code>a_lagging_dub_is_not_padded_with_episodes_that_have_none</code> tells you what broke. <code>test_episodes</code> does not.</p><p><strong>Assert something.</strong> A test that only prints is a debugging scratchpad and does not belong in the suite.</p><p><strong>Keep parsing pure and test it against fixtures.</strong> Saved HTML or JSON in, structured data out. When a site changes its markup that is a failing parser test rather than an afternoon of guessing.</p><p><strong>Put anything that touches the network behind a gate.</strong> <code>#[ignore]</code> for a probe, <code>ANISPHERE_SMOKE</code> for a pipeline. The offline suites have to stay runnable on a plane.</p><h2 id="the-two-gates" tabindex="-1">The two gates <a class="header-anchor" href="#the-two-gates" aria-label="Permalink to &quot;The two gates&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>The frontend and Rust suites in parallel, nothing else. This is what runs in front of <code>npm run tauri:dev</code>, and there it runs with <code>--changed</code> so only the side you edited goes. A side is recorded as green only after it has actually passed, so a red suite is never skipped.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci:local</span></span></code></pre></div><p>The full deterministic gate: tooling contracts, TypeScript, Prettier, ESLint at zero warnings, Knip, the frontend suite, the frontend build, <code>cargo fmt --check</code>, the offline Rust suite, and Clippy at <code>-D warnings</code>.</p><p>Sonar analysis is separate because it needs a running server and a token. The frontend and backend have independent 80% and 60% gates; <a href="./SonarQube">SonarQube</a> documents the local workflow.</p><h2 id="sonar-project-checks" tabindex="-1">Sonar project checks <a class="header-anchor" href="#sonar-project-checks" aria-label="Permalink to &quot;Sonar project checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonar:checks</span></span></code></pre></div><p>This runs repository-specific static contracts from <code>scripts/sonar/project-checks.mjs</code>: dependency direction and cycles, source and test layout, Tauri command boundaries, matching error codes, file documentation and naming, locale parity and placeholders, localized interface copy, safe resource reads, adaptive classes and static assets.</p><p>The command writes <code>.tool/sonar/external-issues-frontend.json</code> and <code>.tool/sonar/external-issues-backend.json</code>. It does not pretend those findings are executable tests; <code>npm run sonar</code> imports them beside Sonar&#39;s own JavaScript, TypeScript, Rust and Clippy findings.</p><h2 id="reading-the-output" tabindex="-1">Reading the output <a class="header-anchor" href="#reading-the-output" aria-label="Permalink to &quot;Reading the output&quot;">​</a></h2><p>All three engines print the same block, so the shape does not change when you switch suites:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Test Files  67 passed (67)</span></span>
<span class="line"><span>      Tests  335 passed (335)</span></span>
<span class="line"><span>   Start at  02:34:56</span></span>
<span class="line"><span>   Duration  67.82s (build 27.70s, tests 40.12s)</span></span></code></pre></div><p>For cargo, <code>build</code> and <code>tests</code> are split out because cargo times only the test phase. A long build with a short test time means you changed something that forced a recompile, not that the suite got slower.</p><h2 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage:frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage:rust</span></span></code></pre></div><p>These write <code>coverage/lcov.info</code> and <code>coverage/rust-lcov.info</code>. Vitest and cargo-llvm-cov only measure; Sonar enforces 80% for the frontend and 60% for the backend. <code>npm run sonar</code> rebuilds both reports automatically. See <a href="/AniSphere.docs/coverage">Coverage</a> and <a href="./SonarQube">SonarQube</a>.</p>`,50)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
